package ro.leo.visual;
import android.app.*;import android.content.*;import android.os.Bundle;import java.util.*;
public final class NotificationSettingsActivity extends LeoActivity {
    protected void onResume(){super.onResume();show();}
    private void show(){String[] previews={"Ascunse","Doar titluri","Titlu și text"};int mode=Math.max(0,Math.min(2,getSharedPreferences("appearance",0).getInt("lock-preview",0)));list("Notificări Leo",Arrays.asList("Deschide centrul de notificări","La blocare · "+previews[mode],"Sunet pentru notificări","Acces Leo · "+(LeoNotificationService.active==null?"Neconectat":"Conectat"),"Insigne Telefon / Mesaje"),0,new Choice(){public void pick(int i){if(i==0)startActivity(new Intent(NotificationSettingsActivity.this,NotificationsActivity.class));else if(i==1)options("Previzualizare la blocare",new String[]{"Ascunde","Doar titluri","Titlu și text vizibil"},new Choice(){public void pick(final int n){if(n==2)options("Text vizibil pe ecranul blocat",new String[]{"Anulează","Afișează textul"},new Choice(){public void pick(int yes){if(yes==1)savePreview(n);}});else savePreview(n);}});else if(i==2)startActivity(new Intent(NotificationSettingsActivity.this,SoundSettingsActivity.class));else if(i==3){LeoNotificationService.reconnect(NotificationSettingsActivity.this);notice("Reconectare cerută; actualizează pagina");}else notice("Număr local de SMS necitite și apeluri pierdute. Conversația și istoricul le marchează văzute; nimic nu este trimis automat.");}},"Actualiz.",new Runnable(){public void run(){show();}});}
    private void savePreview(int value){getSharedPreferences("appearance",0).edit().putInt("lock-preview",value).apply();show();}
}
